const PIZZA_HOT_API_URL = "https://script.google.com/macros/s/AKfycby5pD8nlMt62GdcAeHZKTj7cKF4xFOigK_Qhn7JV778mCIbwp0sO2eHKSnIt6TL57ZM/exec?api=PIZZA_HOT",
    PIZZA_HOT_CACHE_KEY = "pizza_hot_cache", PIZZA_HOT_CACHE_TIME_KEY = "pizza_hot_cache_time", CACHE_DURATION = 36e5, pizzaElements = {};
let allPizzaOffers = [];

async function loadPizzaOffers(e = !1) {
    setPizzaState("loading");
    try {
        if (!e) {
            const e = getPizzaCache();
            if (null !== e) return console.log("[Pizza Hot] 使用本機快取資料"), allPizzaOffers = e.filter(isValidPizzaOffer), void renderPizzaOffers(allPizzaOffers, !1)
        }
        console.log("[Pizza Hot] 呼叫 API 取得資料");
        const t = await fetch(PIZZA_HOT_API_URL, {method: "GET", redirect: "follow", cache: "no-store"});
        if (!t.ok) throw new Error(`HTTP ${t.status}`);
        const a = await t.json();
        if (!Array.isArray(a)) throw new Error("API 回傳格式不是陣列");
        savePizzaCache(a), allPizzaOffers = a.filter(isValidPizzaOffer), renderPizzaOffers(allPizzaOffers, !1)
    } catch (e) {
        console.error("Pizza Hot API 載入失敗", {name: e.name, message: e.message, stack: e.stack}), setPizzaState("error")
    }
}

function getPizzaCache() {
    try {
        const e = localStorage.getItem("pizza_hot_cache"), t = localStorage.getItem("pizza_hot_cache_time");
        if (!e || !t) return null;
        const a = Date.now() - Number(t);
        if (!Number.isFinite(a) || a >= 36e5) return clearPizzaCache(), null;
        const r = JSON.parse(e);
        return Array.isArray(r) ? r : (clearPizzaCache(), null)
    } catch (e) {
        return console.warn("Pizza Hot 本機快取讀取失敗將重新呼叫 API", e), clearPizzaCache(), null
    }
}

function savePizzaCache(e) {
    try {
        localStorage.setItem("pizza_hot_cache", JSON.stringify(e)), localStorage.setItem("pizza_hot_cache_time", String(Date.now()))
    } catch (e) {
        console.warn("Pizza Hot 本機快取寫入失敗", e)
    }
}

function clearPizzaCache() {
    localStorage.removeItem("pizza_hot_cache"), localStorage.removeItem("pizza_hot_cache_time")
}

function isValidPizzaOffer(e) {
    return e && "object" == typeof e && e.code && e.detail
}

function filterPizzaOffers() {
    const e = pizzaElements.search.value.trim().toLocaleLowerCase("zh-Hant-TW");
    if (!e) return void renderPizzaOffers(allPizzaOffers, !1);
    renderPizzaOffers(allPizzaOffers.filter(t => String(t.detail).toLocaleLowerCase("zh-Hant-TW").includes(e)), !0)
}

function renderPizzaOffers(e, t) {
    if (pizzaElements.grid.replaceChildren(), 0 === e.length) return pizzaElements.count.textContent = t ? "找不到符合條件的優惠" : "目前沒有優惠資料", void setPizzaState("empty");
    const a = document.createDocumentFragment();
    e.forEach(e => {
        const t = document.createElement("article");
        t.className = "pizza-card";
        const r = document.createElement("p");
        r.className = "pizza-card__code", r.textContent = `優惠代碼 ${String(e.code)}`;
        const n = document.createElement("p");
        n.className = "pizza-card__detail", n.textContent = String(e.detail);
        const i = document.createElement("p");
        i.className = "pizza-card__date", i.textContent = e.endDate ? `優惠截止日期${formatPizzaDate(e.endDate)}` : "優惠截止日期未提供", t.append(r, n, i), a.append(t)
    }), pizzaElements.grid.append(a), pizzaElements.count.textContent = t ? `找到 ${e.length} 組優惠` : `目前共有 ${e.length} 組優惠`, setPizzaState("success")
}

function formatPizzaDate(e) {
    const t = String(e).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return t ? `${t[1]}/${t[2]}/${t[3]}` : String(e)
}

function setPizzaState(e) {
    pizzaElements.loading.hidden = "loading" !== e, pizzaElements.error.hidden = "error" !== e, pizzaElements.empty.hidden = "empty" !== e, pizzaElements.reload.hidden = "error" !== e, "loading" === e ? (pizzaElements.grid.replaceChildren(), pizzaElements.search.disabled = !0, pizzaElements.count.textContent = "正在取得優惠資料...") : pizzaElements.search.disabled = !1, "error" === e && (pizzaElements.grid.replaceChildren(), pizzaElements.count.textContent = "優惠資料載入失敗")
}

document.addEventListener("DOMContentLoaded", () => {
    pizzaElements.search = document.querySelector("#pizza-search"), pizzaElements.grid = document.querySelector("#pizza-card-grid"), pizzaElements.loading = document.querySelector("#pizza-loading"), pizzaElements.error = document.querySelector("#pizza-error"), pizzaElements.empty = document.querySelector("#pizza-empty"), pizzaElements.count = document.querySelector("#pizza-result-count"), pizzaElements.reload = document.querySelector("#pizza-reload"), pizzaElements.search.addEventListener("input", filterPizzaOffers), pizzaElements.reload.addEventListener("click", () => {
        clearPizzaCache(), loadPizzaOffers(!0)
    }), loadPizzaOffers()
});